import React, { useCallback, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function BaristaMenuPage() {
  const navigate = useNavigate();

  const [items, setItems] = useState([
    {
      name: "Caramel Latte Regular",
      price: 241.0,
      count: 0,
      img: "https://cooktoria.com/wp-content/uploads/2016/02/Caramel-Macchiato-Recipe-sq-1.jpg",
    },
    {
      name: "Affogato Regular",
      price: 136.0,
      count: 0,
      img: "https://cdn.apartmenttherapy.info/image/upload/f_jpg,q_auto:eco,c_fill,g_auto,w_1500,ar_1:1/k%2FPhoto%2FRecipes%2F2020-07-How-to-make-affogato-at-home%2FKitchn_HowTo_Affogato_0281",
    },
    {
      name: "Hot Chocolate Large",
      price: 225.0,
      count: 0,
      img: "https://pbs.twimg.com/media/CwKfrSlUMAAx6ny.jpg",
    },
    {
      name: "Hot Chocolate Regular",
      price: 210.0,
      count: 0,
      img: "https://pbs.twimg.com/media/CwKfrSlUMAAx6ny.jpg",
    },
    {
      name: "Irish Cappuccino Large",
      price: 268.0,
      count: 0,
      img: "https://www.foodandwine.com/thmb/TNVoBB4XaCn6zBdeCCrwmRRZE-M=/1500x0/filters:no_upscale():max_bytes(150000):strip_icc()/Why-Irish-Coffee-Should-Replace-The-Espresso-Martini-FT-BLOG0922-2000-0c1acd57e2f54aaeb41aecd1e0885dd3.jpg",
    },
    {
      name: "Hazelnut Latte Regular",
      price: 281.0,
      count: 0,
      img: "https://lh3.googleusercontent.com/proxy/GF30NR96GHauMAu278DIiYKsSaus7oWneaGUAFuUtp5qlMY6tHy1gH2feB0DPYvWvi8hnn-oRMiz0iHzU76U7bsD-sdhjhHEBVLYTOIF_A1jfO3xlE1jQPH4guZ0",
    },
    {
      name: "Orange Zest Latte Regular",
      price: 241.0,
      count: 0,
      img: "https://www.barista.co.in/sites/default/files/2024-07/Orange%20zest%20latte.webp",
    },
  ]);

  const updateItemCount = useCallback((index, increment) => {
    setItems((prev) =>
      prev.map((it, i) => {
        if (i !== index) return it;
        const nextCount = increment ? it.count + 1 : Math.max(0, it.count - 1);
        return { ...it, count: nextCount };
      })
    );
  }, []);

  const hasItems = useMemo(() => items.some((i) => i.count > 0), [items]);

  function generateBill() {
    let billData = {};
    let any = false;
    items.forEach((item) => {
      if (item.count > 0) {
        billData[item.name] = { count: item.count, price: item.price };
        any = true;
      }
    });

    if (any) {
      localStorage.setItem("billData", JSON.stringify(billData));
      navigate("/barista-bill");
    } else {
      alert("No items in the bill.");
    }
  }

  return (
    <>
      <style>{`
        body {
          font-family: Arial, sans-serif;
        }

        header {
          text-align: center;
          padding: 20px;
          background-color: #f0f0f0;
          border-radius: 10px;
        }
        #menu-text{
          font-family:'Courier New', Courier, monospace;
          font-size: 100;
        }

        .coffee-image {
          width: 50px;
          height: 50px;
          margin-right: 10px;
          border-radius: 5px;
        }

        #bill-container {
          padding: 20px;
          border: 2px solid #ec2020;
          border-radius: 10px;
          background-color: #f9f9f9;
          display: none;
        }

        #view-bill-btn {
          background-color: #4CAF50;
          color: white;
          padding: 10px 20px;
          font-size: 16px;
          border: none;
          border-radius: 20px;
          cursor: pointer;
          margin-top: 20px;
        }

        #view-bill-btn:hover {
          background-color: #45a049;
        }
      `}</style>

      <header>
        <img
          src="https://stores.barista.co.in/wp-content/uploads/2024/04/Barista-Circle-Logo-PNG-1000x1000-1.png"
          width="100px"
          height="100px"
          alt=""
        />
        <br /> <br />
        <h1 id="menu-text">MENU</h1>
      </header>
      <main className="container mt-4">
        <div className="barista">
          <ul className="list-group menu-items">
            {items.map((item, index) => {
              const itemControlText = item.count > 0 ? `x ${item.count} ` : "";
              return (
                <li
                  key={item.name}
                  className="list-group-item d-flex justify-content-between align-items-center"
                >
                  <img src={item.img} alt={item.name} className="coffee-image" />
                  <span>
                    {item.name} - ₹{item.price.toFixed(2)}
                  </span>
                  <div className="item-controls">
                    <button
                      className="btn btn-danger btn-sm minus-btn"
                      data-index={index}
                      style={{ display: item.count > 0 ? "inline-block" : "none" }}
                      onClick={() => updateItemCount(index, false)}
                      type="button"
                    >
                      -
                    </button>
                    <span className="item-count">{itemControlText}</span>
                    <button
                      className="btn btn-danger btn-sm plus-btn"
                      data-index={index}
                      onClick={() => updateItemCount(index, true)}
                      type="button"
                    >
                      Add +
                    </button>
                  </div>
                </li>
              );
            })}
          </ul>
          <button id="view-bill-btn" className="btn btn-success" onClick={generateBill} disabled={!hasItems}>
            View Bill
          </button>
          <div id="bill-container" className="mt-3"></div>
        </div>
      </main>
    </>
  );
}
